PREVIEW_HTML = '<!doctype html>\n<html lang="ru">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n  <meta name="color-scheme" content="light dark">\n  <title>SUNPARK · Меню</title>\n  <link rel="stylesheet" href="/menu-preview.css">\n  <script src="https://telegram.org/js/telegram-web-app.js"></script>\n  <script src="/menu-preview.js" defer></script>\n</head>\n<body>\n  <div class="app">\n    <header class="masthead">\n      <div class="topline"><span class="eyebrow">КУХНЯ · БАР · ХОРОШИЙ ДЕНЬ</span><button id="theme-switch" class="theme-switch" aria-label="Сменить вариант оформления">Сменить вид</button></div>\n      <div class="brand"><svg class="brand-symbol" viewBox="0 0 64 64" aria-hidden="true"><path d="M32 55V29M32 40C13 40 9 21 9 12c20 0 23 12 23 28Zm0-9C32 11 45 7 57 7c0 18-10 24-25 24Z" fill="none" stroke="currentColor" stroke-width="2.5"/></svg><h1>SUNPARK<span>меню</span></h1><span class="edition" id="edition">04 / ДНЕВНОЙ</span></div>\n      <p class="intro" id="intro">Найдите своё любимое.</p>\n      <label class="search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/></svg><input id="search" type="search" placeholder="Найти блюдо или напиток" autocomplete="off" aria-label="Поиск по меню"><kbd>⌕</kbd></label>\n    </header>\n    <nav id="groups" class="groups" aria-label="Части меню"></nav>\n    <main>\n      <nav id="categories" class="categories" aria-label="Разделы меню"></nav>\n      <div class="section-heading"><div><span class="eyebrow" id="section-kicker">МЕНЮ SUNPARK</span><h2 id="section-title">Загружаем меню…</h2></div><span id="item-count" class="count"></span></div>\n      <div id="status" class="status" role="status" aria-live="polite">Проверяем доступ администратора…</div>\n      <div id="items" class="items"></div>\n      <p id="category-footer" class="category-footer"></p>\n    </main>\n    <footer class="page-footer"><span>SUNPARK</span><span>Состав — по нажатию на блюдо</span></footer>\n  </div>\n  <dialog id="dish-dialog" aria-labelledby="dish-name">\n    <button id="close-dialog" class="close-dialog" aria-label="Закрыть состав">×</button>\n    <div class="sheet-handle" aria-hidden="true"></div>\n    <span class="eyebrow" id="dish-section"></span>\n    <h2 id="dish-name"></h2>\n    <p class="dish-price" id="dish-price"></p>\n    <div class="detail-rule"></div>\n    <h3>Состав и подача</h3>\n    <p id="dish-description" class="dish-description"></p>\n    <p id="dish-footer" class="dish-footer"></p>\n    <button id="back-to-menu" class="back-to-menu">Вернуться к меню</button>\n  </dialog>\n</body>\n</html>\n'
